import re

def solve(env, goal):
    goal_l = goal.lower()
    obj_m = re.search(r"(?:heat|warm|hot|warm up|heat up)\s+(?:some|a|an|the)?\s*([a-z]+)", goal_l)
    obj_type = obj_m.group(1) if obj_m else None
    if obj_type is None:
        obj_type = goal_l.split()[0] if goal_l else "tomato"
    recv_m = re.search(r"(?:in|on|inside|into)\s+(?:a|an|the)?\s*([a-z]+)", goal_l)
    recv_type = recv_m.group(1) if recv_m else "fridge"

    def norm(t):
        return t.rstrip("0123456789 ").strip()

    def find_objects_in(text, want):
        res = []
        for m in re.finditer(r"([a-z]+)\s+(\d+)", text):
            if norm(m.group(1)) == want:
                res.append(m.group(0))
        return res

    def find_receptacles(text, want):
        res = []
        for m in re.finditer(r"([a-z]+)\s+(\d+)", text):
            if norm(m.group(1)) == want:
                res.append(m.group(0))
        return res

    def held_object():
        txt = env.observation
        m = re.search(r"You are carrying ([a-z]+) (\d+)", txt)
        if m:
            return m.group(0)
        return None

    def do(cmd):
        return env.step(cmd)

    def ensure_open(r):
        txt = env.observation
        if "is closed" in txt.lower():
            do("open " + r)

    # parse initial room description from first observation
    initial = env.observation
    # collect all receptacles mentioned
    recs = []
    seen = set()
    for m in re.finditer(r"\b([a-z]+)\s+(\d+)\b", initial):
        r = m.group(0)
        if r not in seen:
            seen.add(r)
            recs.append(r)

    target_obj = None
    target_place = None

    # check if already holding target
    held = held_object()
    if held and norm(held.split()[0]) == obj_type:
        target_obj = held

    # search for object in all receptacles
    if target_obj is None:
        for r in recs:
            do("go to " + r)
            ensure_open(r)
            txt = env.observation
            objs = find_objects_in(txt, obj_type)
            if objs:
                target_obj = objs[0]
                target_place = r
                break
            held = held_object()
            if held and norm(held.split()[0]) == obj_type:
                target_obj = held
                break

    # If not found yet, try opening all containers and re-scanning (some may hide objects)
    if target_obj is None:
        for r in recs:
            do("go to " + r)
            ensure_open(r)
            txt = env.observation
            objs = find_objects_in(txt, obj_type)
            if objs:
                target_obj = objs[0]
                target_place = r
                break

    # take object if not held
    if target_obj:
        held = held_object()
        if not (held and norm(held.split()[0]) == obj_type):
            if target_place:
                do("go to " + target_place)
                ensure_open(target_place)
                do("take " + target_obj + " from " + target_place)

    # heat with microwave
    mic = None
    mics = find_receptacles(env.observation, "microwave")
    if mics:
        mic = mics[0]
    if mic is None:
        # search all receptacles for microwave
        for r in recs:
            if norm(r.split()[0]) == "microwave":
                mic = r
                break
    if mic is None:
        mic = "microwave 1"
    do("go to " + mic)
    ensure_open(mic)
    held = held_object()
    if held:
        do("heat " + held + " with " + mic)

    # find target receptacle
    held = held_object()
    if held:
        recs2 = find_receptacles(env.observation, recv_type)
        if not recs2:
            # search initial list
            for r in recs:
                if norm(r.split()[0]) == recv_type:
                    recs2.append(r)
                    break
        if not recs2:
            # try recv_type 1
            recs2 = [recv_type + " 1"]
        target_rec = recs2[0]
        do("go to " + target_rec)
        ensure_open(target_rec)
        do("move " + held + " to " + target_rec)

    return None
